//! The About Comic Editor dialog: version, licence, the external tools in use
//! and the projects the app is built on, with their licences.

use std::path::{Path, PathBuf};

use egui::{RichText, vec2};

use super::widgets::section;
use crate::util::{tool, tool_path};

const REPOSITORY: &str = env!("CARGO_PKG_REPOSITORY");
const COPYRIGHT: &str = "Copyright © 2026 Alexander Anderson";
/// Full licence texts of everything built into the app. Generated by
/// `packaging/third-party-licenses.sh` for releases.
const LICENSES_FILE: &str = "THIRD_PARTY_LICENSES.txt";

/// Main components, with their licences and what they're used for. The
/// licences file covers everything else.
const COMPONENTS: &[(&str, &str, &str, &str)] = &[
    ("egui and eframe", "https://github.com/emilk/egui", "MIT or Apache-2.0", "User interface"),
    ("SQLite", "https://sqlite.org", "Public domain", "Library database"),
    ("image", "https://github.com/image-rs/image", "MIT or Apache-2.0", "Reading pages and covers"),
    ("dav1d", "https://code.videolan.org/videolan/dav1d", "BSD-2-Clause", "AVIF decoding"),
    ("libavif", "https://github.com/AOMediaCodec/libavif", "BSD-2-Clause", "AVIF encoding (avifenc)"),
    ("libaom", "https://aomedia.googlesource.com/aom", "BSD-2-Clause", "AV1 encoder used by avifenc"),
    ("SVT-AV1", "https://gitlab.com/AOMediaCodec/SVT-AV1", "BSD-3-Clause-Clear", "AV1 encoder used by avifenc"),
    ("rav1e", "https://github.com/xiph/rav1e", "BSD-2-Clause", "AV1 encoder used by avifenc"),
    ("UnRAR", "https://www.rarlab.com", "UnRAR licence (freeware)", "Reading CBR files"),
    ("Ubuntu, Hack and Noto Emoji", "https://github.com/emilk/egui/tree/main/crates/epaint_default_fonts", "UFL-1.0, MIT, OFL-1.1", "Fallback fonts"),
];

pub struct AboutDialog {
    tools: Vec<Tool>,
    licenses: Option<PathBuf>,
    /// Lines of the licences file, while it's shown instead of the summary.
    viewing: Option<Vec<String>>,
    db_path: PathBuf,
}

struct Tool {
    name: &'static str,
    /// Shown when the tool is missing.
    missing: &'static str,
    path: Option<PathBuf>,
    version: Option<String>,
}

impl AboutDialog {
    pub fn new(db_path: PathBuf) -> Self {
        let tools = vec![
            Tool::probe("unrar", &[], "Not found: CBR files can't be opened."),
            Tool::probe("avifenc", &["--version"], "Not found: comics can't be compressed to AVIF."),
        ];
        Self { tools, licenses: find_licenses(), viewing: None, db_path }
    }

    /// Returns true once the user closes the dialog.
    pub fn show(&mut self, ctx: &egui::Context) -> bool {
        let modal = egui::Modal::new(egui::Id::new("about_dialog")).show(ctx, |ui| match &self.viewing {
            Some(lines) => {
                if show_licenses(ui, lines) {
                    self.viewing = None;
                }
                false
            }
            None => self.summary(ui),
        });
        modal.inner || modal.should_close()
    }

    /// Returns true when Close is clicked.
    fn summary(&mut self, ui: &mut egui::Ui) -> bool {
        ui.set_width(560.0);
        ui.horizontal(|ui| {
            let icon = egui::Image::from_bytes("bytes://comic-editor.svg", include_bytes!("../../packaging/comic-editor.svg"));
            ui.add(icon.fit_to_exact_size(vec2(64.0, 64.0)));
            ui.add_space(8.0);
            ui.vertical(|ui| {
                ui.heading("Comic Editor");
                ui.label(format!("Version {}", env!("CARGO_PKG_VERSION")));
                ui.weak(env!("CARGO_PKG_DESCRIPTION"));
            });
        });
        ui.add_space(8.0);
        ui.label(format!("{COPYRIGHT}. Released under the MIT licence."));
        ui.horizontal(|ui| {
            ui.hyperlink_to("Source code on GitHub", REPOSITORY);
            ui.label("·");
            ui.hyperlink_to("Report a problem", format!("{REPOSITORY}/issues"));
        });

        section(ui, "External tools");
        egui::Grid::new("about_tools").num_columns(2).spacing(vec2(12.0, 4.0)).show(ui, |ui| {
            for tool in &self.tools {
                ui.label(RichText::new(tool.name).strong());
                tool.status(ui);
                ui.end_row();
            }
        });

        section(ui, "Built with");
        egui::Grid::new("about_components").num_columns(3).spacing(vec2(12.0, 4.0)).show(ui, |ui| {
            for &(name, url, license, purpose) in COMPONENTS {
                ui.hyperlink_to(name, url);
                ui.label(license);
                ui.weak(purpose);
                ui.end_row();
            }
        });
        ui.add_space(4.0);
        ui.weak("And many other Rust libraries; see Third-Party Licences for the full list.");
        ui.horizontal(|ui| {
            ui.weak("Comic metadata is provided by");
            ui.hyperlink_to("ComicVine", "https://comicvine.gamespot.com");
            ui.weak("and manga metadata by");
            ui.hyperlink_to("AniList", "https://anilist.co");
        });

        section(ui, "Files");
        egui::Grid::new("about_files").num_columns(2).spacing(vec2(12.0, 4.0)).show(ui, |ui| {
            path_row(ui, "Library", Some(&self.db_path));
            path_row(ui, "Settings", crate::settings::settings_path().as_deref());
        });
        ui.separator();

        let mut close = false;
        ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
            close = ui.button("Close").clicked();
            let button = ui.add_enabled(self.licenses.is_some(), egui::Button::new("Third-Party Licences…"));
            let button = button.on_disabled_hover_text("The licence texts aren't included in this build.");
            if button.clicked()
                && let Some(path) = &self.licenses
            {
                match std::fs::read(path) {
                    // Some packages' copyright files aren't valid UTF-8.
                    Ok(bytes) => self.viewing = Some(String::from_utf8_lossy(&bytes).lines().map(str::to_owned).collect()),
                    Err(e) => eprintln!("couldn't read {}: {e}", path.display()),
                }
            }
        });
        close
    }
}

impl Tool {
    /// Finds `name` and asks it for its version (unrar prints it when run
    /// without arguments).
    fn probe(name: &'static str, version_args: &[&str], missing: &'static str) -> Self {
        let path = tool_path(name);
        let version = path.as_ref().and_then(|_| {
            let output = tool(name).args(version_args).output().ok()?;
            let text = String::from_utf8_lossy(&output.stdout);
            parse_version(name, text.lines().find(|line| !line.trim().is_empty())?)
        });
        Self { name, missing, path, version }
    }

    fn status(&self, ui: &mut egui::Ui) {
        let Some(path) = &self.path else {
            ui.colored_label(ui.visuals().warn_fg_color, self.missing);
            return;
        };
        let version = self.version.as_deref().unwrap_or("unknown version");
        if is_bundled(path) {
            ui.label(format!("{version}, included with Comic Editor"));
        } else {
            ui.label(format!("{version}, {}", path.display()));
        }
    }
}

/// The version number from the first line of a tool's output:
/// "UNRAR 7.13 freeware      Copyright (c) …" or
/// "Version: 1.4.2 (dav1d [dec]:1.5.4, …)".
fn parse_version(name: &str, line: &str) -> Option<String> {
    let version = match name {
        "unrar" => line.trim().strip_prefix("UNRAR ")?.split("freeware").next()?,
        _ => line.trim().strip_prefix("Version: ")?.split(" (").next()?,
    };
    Some(version.trim().to_owned()).filter(|v| !v.is_empty())
}

/// Whether `path` is inside the running AppImage, rather than installed on
/// the system.
fn is_bundled(path: &Path) -> bool {
    std::env::var_os("APPDIR").is_some_and(|dir| path.starts_with(dir))
}

/// The licences file: in `share/doc` beside the binary's `bin` folder (the
/// AppImage, or as installed by install.sh), or next to the binary (an
/// unpacked release).
fn find_licenses() -> Option<PathBuf> {
    let exe = std::env::current_exe().ok()?;
    let dir = exe.parent()?;
    [dir.join("../share/doc/comic-editor").join(LICENSES_FILE), dir.join(LICENSES_FILE)]
        .into_iter()
        .find(|path| path.is_file())
}

fn path_row(ui: &mut egui::Ui, label: &str, path: Option<&Path>) {
    ui.label(RichText::new(label).strong());
    match path {
        Some(path) => ui.add(egui::Label::new(path.display().to_string()).selectable(true)),
        None => ui.weak("Unknown"),
    };
    ui.end_row();
}

/// The full licence texts. Returns true when Back is clicked.
fn show_licenses(ui: &mut egui::Ui, lines: &[String]) -> bool {
    ui.set_width(760.0);
    ui.heading("Third-Party Licences");
    ui.weak("Comic Editor is built on these projects, under the licences below.");
    ui.separator();

    let font = egui::TextStyle::Monospace.resolve(ui.style());
    let row_height = ui.text_style_height(&egui::TextStyle::Monospace);
    egui::ScrollArea::both().max_height(480.0).auto_shrink([false, true]).show_rows(
        ui,
        row_height,
        lines.len(),
        |ui, rows| {
            for line in &lines[rows] {
                ui.add(egui::Label::new(RichText::new(line).font(font.clone())).extend());
            }
        },
    );
    ui.separator();

    let mut back = false;
    ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
        back = ui.button("Back").clicked();
    });
    back
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tool_versions_are_parsed() {
        let unrar = "UNRAR 7.13 freeware      Copyright (c) 1993-2026 Alexander Roshal";
        assert_eq!(parse_version("unrar", unrar).as_deref(), Some("7.13"));
        let beta = "UNRAR 7.30 beta 1 freeware      Copyright (c) 1993-2026 Alexander Roshal";
        assert_eq!(parse_version("unrar", beta).as_deref(), Some("7.30 beta 1"));
        let avifenc = "Version: 1.4.2 (dav1d [dec]:1.5.4, aom [enc/dec]:v3.15.2)";
        assert_eq!(parse_version("avifenc", avifenc).as_deref(), Some("1.4.2"));
        assert_eq!(parse_version("avifenc", "something else"), None);
    }
}
